--3‑1 游戏漏斗统计（DEMO演示数据 is_demo = 1）SELECT  event_id,  COUNT(DISTINCT user_id) AS user_cntFROM track_eventsWHERE is_demo = 1 AND event_id IN ('e01','e03','e04','e06')GROUP BY event_id;--3‑2 AIGC采纳率统计SELECT  SUM(IF(event_id='e09',1,0)) AS success_cnt,  SUM(IF(event_id='e10',1,0)) AS adopt_cnt,  ROUND(SUM(IF(event_id='e10',1,0)) / SUM(IF(event_id='e09',1,0)),4) AS adopt_rateFROM track_eventsWHERE is_demo = 1;